1	/**
2	 * SovereignBridge - Real-time WebSocket bridge to the POG2 Backend.
3	 * Decouples the 3D Viewer from the heavy POG2 Orchestrator while maintaining state parity.
4	 */
5	export class SovereignBridge {
6	    private static instance: SovereignBridge;
7	    private ws: WebSocket | null = null;
8	    private listeners: ((msg: any) => void)[] = [];
9	    private tickListeners: ((msg: any) => void)[] = [];
10	    private logListeners: ((log: any) => void)[] = [];
11	    private engine: any = null;
12	    private retryCount = 0;
13	    private state: any = {
14	        tick: 0,
15	        avatar: { x: 3200, y: 3200, plane: 0, username: 'POG2_Sovereign', isBusy: false },
16	        inventory: [],
17	        activeModule: 'idle'
18	    };
19	
20	    private constructor() {
21	        this.connect();
22	    }
23	
24	    public static getInstance(): SovereignBridge {
25	        if (!this.instance) {
26	            this.instance = new SovereignBridge();
27	        }
28	        return this.instance;
29	    }
30	
31	    private connect() {
32	        // POG2 Switchboard Default Port: 8789
33	        this.ws = new WebSocket('ws://localhost:8789');
34	
35	        this.ws.onopen = () => {
36	            this.retryCount = 0;
37	            console.log('%c[BRIDGE] Connected to Sovereign Switchboard', 'color: #00ff00; font-weight: bold;');
38	        };
39	
40	        this.ws.onmessage = (event) => {
41	            try {
42	                const msg = JSON.parse(event.data);
43	                if (msg.type === 'state_sync') {
44	                    this.state = msg.state;
45	                    this.notifyListeners(msg);
46	                } else if (msg.type === 'tick_event') {
47	                    this.notifyTickListeners(msg);
48	                } else if (msg.type === 'SYSTEM_LOG') {
49	                    this.notifyLogListeners(msg.payload);
50	                } else if (msg.type === 'log') {
51	                    // console.debug('[POG2 LOG]', msg.message);
52	                }
53	            } catch (err) {
54	                console.error('[BRIDGE] Parse error:', err);
55	            }
56	        };
57	
58	        this.ws.onclose = () => {
59	            this.retryCount++;
60	            const delay = Math.min(5000 * Math.pow(2, this.retryCount - 1), 60000);
61	            if (this.retryCount <= 3) {
62	                console.warn(`[BRIDGE] Socket closed. Retry #${this.retryCount} in ${delay / 1000}s...`);
63	            }
64	            setTimeout(() => this.connect(), delay);
65	        };
66	
67	        this.ws.onerror = (err) => {
68	            // console.error('[BRIDGE] Socket error:', err);
69	        };
70	    }
71	
72	    public onSync(callback: (msg: any) => void) {
73	        this.listeners.push(callback);
74	    }
75	
76	    public onTick(callback: (msg: any) => void) {
77	        this.tickListeners.push(callback);
78	    }
79	
80	    public onSystemLog(callback: (log: any) => void) {
81	        this.logListeners.push(callback);
82	    }
83	
84	    private notifyListeners(msg: any) {
85	        this.listeners.forEach(l => l(msg));
86	    }
87	
88	    private notifyTickListeners(msg: any) {
89	        this.tickListeners.forEach(l => l(msg));
90	    }
91	
92	    private notifyLogListeners(log: any) {
93	        this.logListeners.forEach(l => l(log));
94	    }
95	
96	    public getState() {
97	        return this.state;
98	    }
99	
100	    public setEngine(engine: any) {
101	        this.engine = engine;
102	    }
103	
104	    /**
105	     * handleCommand - Clinical routing for the Sovereign Console.
106	     */
107	    public handleCommand(cmd: string) {
108	        const parts = cmd.trim().split(/\s+/);
109	        const command = parts[0].toLowerCase();
110	        const args = parts.slice(1);
111	
112	        this.log('CMD', 'User', `> ${cmd}`);
113	
114	        switch (command) {
115	            case '/tp':
116	            case '/teleport':
117	                if (args.length >= 2) {
118	                    const x = parseInt(args[0]);
119	                    const z = parseInt(args[1]);
120	                    if (!isNaN(x) && !isNaN(z)) {
121	                        this.engine?.teleportTo(x, z);
122	                    } else {
123	                        this.log('ERROR', 'Bridge', 'Invalid coordinates: /tp <x> <z>');
124	                    }
125	                } else {
126	                    this.log('ERROR', 'Bridge', 'Usage: /tp <x> <z>');
127	                }
128	                break;
129	
130	            case '/spawn':
131	                if (args.length >= 1) {
132	                    const id = parseInt(args[0]);
133	                    if (!isNaN(id)) {
134	                        this.engine?.spawnNPCCommand(id);
135	                    } else {
136	                        this.log('ERROR', 'Bridge', 'Invalid ID: /spawn <id>');
137	                    }
138	                } else {
139	                    this.log('ERROR', 'Bridge', 'Usage: /spawn <id>');
140	                }
141	                break;
142	
143	            case '/collision':
144	                const active = args[0] === 'on' || args[0] === '1' || args[0] === 'true';
145	                this.engine?.updateCollisionOverlay(active);
146	                break;
147	
148	            case '/export':
149	                this.log('INFO', 'Bridge', 'Manifesting POG2 Synthesis Export...');
150	                const manifest = {
151	                    timestamp: Date.now(),
152	                    chunks: this.engine?.spatialManager?.getIndexedChunkKeys() || [],
153	                    npcs: this.engine?.npcs?.map((n: any) => n.id) || []
154	                };
155	                console.log('[POG2 EXPORT]', manifest);
156	                this.log('INFO', 'Bridge', `Export Consolidated: ${manifest.chunks.length} Chunks, ${manifest.npcs.length} NPCs.`);
157	                break;
158	
159	            default:
160	                // Authoritative Admin Command Relay (Phase 29)
161	                if (command.startsWith('::')) {
162	                    const rawCmd = command.substring(2);
163	                    this.log('CMD', 'Admin', `Relaying Authoritative Trigger: ${rawCmd}`);
164	                    this.sendAction(JSON.stringify({ 
165	                        type: 'ADMIN_COMMAND', 
166	                        payload: {
167	                            command: rawCmd,
168	                            args: args,
169	                            timestamp: Date.now()
170	                        } 
171	                    }));
172	                } else {
173	                    // Relay unknown commands to the backend orchestrator
174	                    this.sendAction(JSON.stringify({ type: 'CONSOLE_COMMAND', payload: cmd }));
175	                }
176	                break;
177	        }
178	    }
179	
180	    /**
181	     * sendAction - Push a manual or autonomous action back to the backend.
182	     */
183	    public sendAction(intent: string) {
184	        if (this.ws?.readyState === WebSocket.OPEN) {
185	            this.ws.send(JSON.stringify({
186	                type: 'command',
187	                intent
188	            }));
189	        }
190	    }
191	
192	    /**
193	     * log - Relay a system event to all subscribers (Clinical HUD console).
194	     */
195	    public log(level: 'INFO' | 'WARN' | 'ERROR' | 'CMD', source: string, message: string) {
196	        const payload = { timestamp: Date.now(), level, source, message };
197	        this.notifyLogListeners(payload);
198	        
199	        // Optionally relay back to orchestrator if needed for forensic persistence
200	        if (this.ws?.readyState === WebSocket.OPEN) {
201	            this.ws.send(JSON.stringify({ type: 'SYSTEM_LOG', payload }));
202	        }
203	    }
204	}
