7	const VARBIT_OUT_DIR = "D:\\sovereign\\memory\\pedagogy\\varbits";
8	
9	export class SovereignVarbitBridge {
10	    private static instance: SovereignVarbitBridge;
11	    private cache: GameCacheLoader;
12	
13	    private constructor() {
14	        this.cache = new GameCacheLoader("C:\\\\ProgramData\\\\Jagex\\\\RuneScape");
15	        if (!fs.existsSync(VARBIT_OUT_DIR)) {
16	            fs.mkdirSync(VARBIT_OUT_DIR, { recursive: true });
