25	    /**
26	     * Extracts a varbit from the "Godhead" cache and saves it to pedagogy.
27	     */
28	    async extractVarbit(id: number) {
29	        const outPath = path.join(VARBIT_OUT_DIR, `vb_${id}.json`);
30	        
31	        // Skip if already extracted
32	        if (fs.existsSync(outPath)) return;
33	
34	        try {
35	            console.log(`[GODHEAD] Synthesizing Varbit ${id}...`);
36	            const entry = await this.cache.getIndexEntryById(cacheMajors.config, cacheConfigPages.varbits);
37	            if (!entry) throw new Error("Varbit config page not found");
38	
39	            const arch = await this.cache.getFileArchive(entry);
40	            const file = arch.find(f => f.fileid === id);
41	            
42	            if (file) {
43	                const varbitDef = (parse as any).varbits.read(file.buffer, this.cache);
44	                fs.writeFileSync(outPath, JSON.stringify(varbitDef, null, 2));
45	                console.log(`[GODHEAD] Resolved Varbit ${id}: BaseVar ${varbitDef.basevar}, ${varbitDef.bitsbins[0]}-${varbitDef.bitsbins[1]}`);
46	                return varbitDef;
47	            }
48	        } catch (e) {
49	            console.error(`  [ERR] Godhead Varbit Extraction Failed for ID ${id}:`, e);
50	        }
51	    }
52	
53	    /**
54	     * Batch extraction for a set of IDs found in a region.
55	     */
56	    async batchExtract(ids: number[]) {
57	        for (const id of ids) {
58	            await this.extractVarbit(id);
59	        }
60	    }
61	
62	    close() {
63	        this.cache.close();
64	    }
65	}
